pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount, bytes memory data) public {
        vm.assume(amount >= address(c).balance);
        vm.assume(target != address(0));
        // deploy an attacker that re-enters Command->withdraw
        Attacker attacker = new Attacker(c);
        attacker.deal();
        uint256 balBefore = address(c).balance;
        // attacker calls Command, triggering re-entrant withdraw during its fallback
        attacker.attack{value: amount}(target, data);
        uint256 balAfter = address(c).balance;
        // invariant: if balance decreased, then the caller must have been the Owner
        // since attacker != Owner, the balance should not decrease
        bool decreased = balAfter < balBefore;
        // the correct contract satisfies: if decreased, then msg.sender in Command was Owner
        // but here msg.sender == attacker (not Owner), so it asserts that decreased is false
        assertTrue(!decreased, "balance decreased without Owner");
    }
}

contract Attacker {
    C public c;
    constructor(C _c) { c = _c; }
    function deal() external payable { require(address(this).balance > 0); }
    function attack(address target, bytes memory data) external payable {
        uint256 bal = address(c).balance;
        if (msg.value < bal) return;
        c.Command{value: msg.value}(target, data);
    }
    fallback() external payable {
        // re-enter withdraw
        c.withdraw();
    }
}

