pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to a reasonable range to avoid overflow in balance tracking
        bound(amount, 1, 100 ether);
        address owner = c.Owner();
        // Record Owner's starting balance
        uint256 ownerStart = owner.balance;
        // Fund the contract
        vm.deal(address(c), amount);
        require(address(c).balance == amount, "funding failed");
        // Owner calls withdraw
        vm.prank(owner);
        c.withdraw();
        // After withdraw, contract balance must be 0
        assertTrue(address(c).balance == 0);
        // General rule: Owner's balance must have increased by exactly the withdrawn amount
        // (which was amount, since contract had no other funds)
        // This holds for reference C for all inputs, but fails for the mutant because
        // the mutant sends the funds to msg.sender (the Owner), but the net effect on Owner's
        // balance is zero (they spent gas and received the same amount from themselves).
        // Actually the Owner paid gas, so a simple equality fails; we measure increase.
        uint256 ownerEnd = owner.balance;
        // The Owner's balance should have increased by exactly the amount (ignoring gas costs).
        // Because we use `vm.prank`, gas is not deducted from the Owner's balance in the test.
        // So the Owner's balance must be ownerStart + amount.
        assertTrue(ownerEnd == ownerStart + amount);
    }
}

